287	// readStoredEvents opens the database file directly and returns every
288	// persisted record in seq order, so tests verify what was actually saved.
289	func readStoredEvents(t *testing.T, path string) []storedEvent {
290		t.Helper()
291		db, err := sql.Open("sqlite", path)
292		if err != nil {
293			t.Fatalf("open sqlite: %v", err)
294		}
295		defer db.Close()
296		rows, err := db.Query("SELECT seq, account, occurred_at, prev_hash, hash FROM events ORDER BY seq")
297		if err != nil {
298			t.Fatalf("query events: %v", err)
299		}
300		defer rows.Close()
301		var events []storedEvent
302		for rows.Next() {
303			var e storedEvent
304			if err := rows.Scan(&e.seq, &e.account, &e.occurredAt, &e.prevHash, &e.hash); err != nil {
305				t.Fatalf("scan event: %v", err)
306			}
307			events = append(events, e)
308		}
309		if err := rows.Err(); err != nil {
310			t.Fatalf("iterate events: %v", err)
311		}
312		return events
313	}
